cases.bad:
.root {
  pointer-events: auto; /* whole band is a drag surface — eats every tap */
  touch-action: none;
}
// handlePointerDown: if (e.target !== e.currentTarget) return; // only background drags

cases.good:
.root { pointer-events: none; } /* band click-through on ALL devices */
.blockDragHandle { position:absolute; bottom:100%; pointer-events:auto; }
// hook: drag starts on [data-cell-id="subtitle-block-drag"] (immediate capture,
// mouse+touch) and on subtitle-block/nav-expand (deferred capture after |deltaY|
// >= 8px — tap still fires click for word lookup / expand)

// probe both levels:
